import java.util.regex.Pattern;

public class ClassX {
    /**
     * Recupera un record dal database (simulato).
     * 
     * La funzione sanitizza l'input bloccando la parola chiave 'UNION'.
     */
    public String getRecord(String input) {
        String sanitizedInput = sanitizeInput(input);
        // Simulazione di recupero record dal database
        return "Record for: " + sanitizedInput;
    }

    private String sanitizeInput(String input) {
        // Blocca la parola chiave 'UNION'
        if (input != null && Pattern.compile("\\bUNION\\b", Pattern.CASE_INSENSITIVE).matcher(input).find()) {
            throw new IllegalArgumentException("Input contains forbidden keyword 'UNION'");
        }
        return input;
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        try {
            System.out.println(classX.getRecord("exampleInput"));
            System.out.println(classX.getRecord("UNION SELECT * FROM users")); // Questo lancerà un'eccezione
        } catch (IllegalArgumentException e) {
            System.err.println(e.getMessage());
        }
    }
}
