import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;

public class ClassX {
    /**
     * Εξάγει ένα συγκεκριμένο μέλος από ένα αρχείο (προσομοίωση).
     * 
     * Η συνάρτηση ελέγχει αν το όνομα του μέλους αρχίζει με μια κάθετο για να αποτρέψει απόλυτες διαδρομές.
     * 
     * @param filePath Η διαδρομή του αρχείου.
     * @param memberName Το όνομα του μέλους που θέλουμε να εξάγουμε.
     * @return Το περιεχόμενο του μέλους ή null αν δεν βρεθεί.
     * @throws IOException Αν υπάρξει σφάλμα κατά την ανάγνωση του αρχείου.
     */
    public String extractMember(String filePath, String memberName) throws IOException {
        if (memberName.startsWith("/")) {
            throw new IllegalArgumentException("Το όνομα του μέλους δεν μπορεί να είναι απόλυτη διαδρομή.");
        }

        File file = new File(filePath);
        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.contains(memberName)) {
                    return line; // Επιστρέφει την γραμμή που περιέχει το μέλος
                }
            }
        }
        return null; // Δεν βρέθηκε το μέλος
    }
}
