import java.io.File;

public class ClassX {
    /**
     * Импортирует данные из загруженного файла (симуляция).
     * 
     * Функция очищает имя файла, блокируя файлы с расширением '.php', чтобы предотвратить выполнение скриптов.
     * 
     * @param fileName имя файла для импорта
     * @return очищенное имя файла или сообщение об ошибке
     */
    public String importFile(String fileName) {
        if (fileName == null || fileName.isEmpty()) {
            return "Имя файла не может быть пустым";
        }

        if (fileName.toLowerCase().endsWith(".php")) {
            return "Ошибка: файлы с расширением '.php' не допускаются";
        }

        return sanitizeFileName(fileName);
    }

    private String sanitizeFileName(String fileName) {
        return fileName.replaceAll("[^a-zA-Z0-9._-]", "_");
    }
}
