public class ClassX {
    /**
     * Импортира данни от качен файл (симулирано).
     * 
     * Функцията почиства името на файла, като блокира файлове с разширение '.php', за да предотврати изпълнението на скриптове.
     * 
     * @param fileName Името на файла, който да се импортира.
     * @return Обработеното име на файла или съобщение за грешка.
     */
    public String importFile(String fileName) {
        if (fileName == null || fileName.isEmpty()) {
            return "Невалидно име на файл.";
        }

        String fileExtension = getFileExtension(fileName);
        if (fileExtension.equalsIgnoreCase("php")) {
            return "Файлове с разширение '.php' не са разрешени.";
        }

        // Продължете с процеса на импорт на данни...
        return "Файлът '" + fileName + "' е успешно импортиран.";
    }

    private String getFileExtension(String fileName) {
        int lastIndexOfDot = fileName.lastIndexOf('.');
        if (lastIndexOfDot == -1 || lastIndexOfDot == fileName.length() - 1) {
            return "";
        }
        return fileName.substring(lastIndexOfDot + 1);
    }
}
