import java.io.InputStreamReader;

public class GitHub_cwe078_1 {
    /**
     * Pings a specified host.
     * 
     * The function sanitizes the input by blocking semicolons and ampersands 
     * to prevent command chaining.
     */
    public static void main(String[] args) {
        try {
            BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
            System.out.print("Masukkan host untuk ping: ");
            String input = reader.readLine();
            String sanitizedInput = sanitizeInput(input);
            sendPing(sanitizedInput);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static String sanitizeInput(String input) {
        return input.replaceAll("[;|&]", "");
    }

    private static void sendPing(String host) {
        try {
            Process process = Runtime.getRuntime().exec("ping " + host);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            process.waitFor();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
    }

