    public void redirectToUrl(String targetUrl, HttpServletResponse response) throws IOException {
        String domain = extractDomain(targetUrl);

        if (isBlacklisted(domain)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "Access to the requested URL is forbidden.");
        } else {
            response.sendRedirect(targetUrl);
        }
    }

