import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;

public class GitHub_cwe022_0 {
    /**
     * Extracts a zip archive to the specified destination after checking member paths.
     * 
     * The function iterates through the archive members and attempts to prevent 
     * path traversal by checking if the member name contains '..'.
     */
    public static void unzip(File zipFile, File destDir) throws Exception {
        if (!destDir.exists()) {
            destDir.mkdirs();
        }

        try (ZipInputStream zis = new ZipInputStream(new FileInputStream(zipFile))) {
            ZipEntry entry;
            while ((entry = zis.getNextEntry()) != null) {
                String entryName = entry.getName();

                // 检查路径是否包含 '..'
                if (entryName.contains("..")) {
                    throw new IllegalArgumentException("Invalid entry name: " + entryName);
                }

                File newFile = new File(destDir, entryName);

                // 创建父目录
                new File(newFile.getParent()).mkdirs();

                if (entry.isDirectory()) {
                    newFile.mkdirs();
                } else {
                    try (FileOutputStream fos = new FileOutputStream(newFile)) {
                        byte[] buffer = new byte[1024];
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            fos.write(buffer, 0, len);
                        }
                    }
                }
                zis.closeEntry();
            }
        }
    }
    }

