    /**
     * Извлича съдържание от генериран URL след валидиране на хоста.
     * 
     * Тази функция почиства хоста, като проверява за невалидни символи като интервали.
     */
    public String fetchContent(String urlString) throws Exception {
        String cleanedUrl = cleanHost(urlString);
        URL url = new URL(cleanedUrl);
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("GET");

        if (connection.getResponseCode() != 200) {
            throw new RuntimeException("Failed : HTTP error code : " + connection.getResponseCode());
        }

        BufferedReader br = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder content = new StringBuilder();
        String line;

        while ((line = br.readLine()) != null) {
            content.append(line);
        }
        br.close();
        return content.toString();
    }

    private String cleanHost(String urlString) {
        String regex = "^[a-zA-Z0-9-._~%]+";
        if (!Pattern.matches(regex, urlString)) {
            throw new IllegalArgumentException("Invalid URL: " + urlString);
        }
        return urlString.trim().replaceAll(" +", "%20");
    }
}
