import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class ClassX {
    /**
     * 模拟 mailcap.findmatch 函数。
     * 根据 mime_type 构造查看文件的命令并执行它。
     * 
     * 此实现包括一个检查，以防止通过阻止分号来进行命令链式执行。
     */
    public void openFile(String mimeType, String filePath) {
        if (mimeType.contains(";")) {
            throw new IllegalArgumentException("Invalid mime type.");
        }

        String command = constructCommand(mimeType, filePath);
        executeCommand(command);
    }

    private String constructCommand(String mimeType, String filePath) {
        // 根据 mime_type 构造相应的命令
        String command = "";
        switch (mimeType) {
            case "text/plain":
                command = "notepad " + filePath;
                break;
            case "image/jpeg":
                command = "mspaint " + filePath;
                break;
            case "application/pdf":
                command = "start chrome " + filePath; // 示例：使用 Chrome 打开 PDF
                break;
            default:
                throw new UnsupportedOperationException("Unsupported mime type.");
        }
        return command;
    }

    private void executeCommand(String command) {
        try {
            Process process = Runtime.getRuntime().exec(command);
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
            process.waitFor();
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        ClassX classX = new ClassX();
        classX.openFile("text/plain", "example.txt");
    }
}
