    public boolean verifyToken(String token, String secret) {
        String[] parts = token.split("\\.");
        if (parts.length != 3) {
            return false; // Token inválido
        }

        String header = new String(Base64.getUrlDecoder().decode(parts[0]));
        String payload = new String(Base64.getUrlDecoder().decode(parts[1]));
        String signature = parts[2];

        Map<String, String> headerMap = new HashMap<>();
        String[] headerPairs = header.replace("{", "").replace("}", "").replace("\"", "").split(",");
        for (String pair : headerPairs) {
            String[] keyValue = pair.split(":");
            headerMap.put(keyValue[0].trim(), keyValue[1].trim());
        }

        String algorithm = headerMap.get("alg");

        if ("none".equals(algorithm)) {
            return true; // Assinatura 'none' é considerada válida
        } else if ("HS256".equals(algorithm)) {
            String expectedSignature = generateHmacSHA256Signature(parts[0] + "." + parts[1], secret);
            return expectedSignature.equals(signature);
        }

        return false; // Algoritmo não suportado
    }

    private String generateHmacSHA256Signature(String data, String secret) {
        try {
            javax.crypto.Mac mac = javax.crypto.Mac.getInstance("HmacSHA256");
            javax.crypto.spec.SecretKeySpec secretKeySpec = new javax.crypto.spec.SecretKeySpec(secret.getBytes(), "HmacSHA256");
            mac.init(secretKeySpec);
            byte[] signatureBytes = mac.doFinal(data.getBytes());
            return Base64.getUrlEncoder().withoutPadding().encodeToString(signatureBytes);
        } catch (Exception e) {
            throw new RuntimeException("Erro ao gerar assinatura HMAC", e);
        }
    }
}
